entries[76440] = { ["name"] = "Pyriumschildstachel", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nPyriumbarren (5)\nPyriumschildstachel\nWird beim Anlegen gebunden\n85\nBenutzen: Bringt einen Pyriumstachel an Eurem Schild an, der beim Blocken manchmal 280 Schaden verursacht.\n\nDurch das Anbringen des Pyriumschildstachels wird der Gegenstand seelengebunden." }
entries[76441] = { ["name"] = "Elementiumschildstachel", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nElementiumbarren (15)\nElementiumschildstachel\n80\nBenutzen: Bringt einen Elementiumstachel an Eurem Schild an, der bei jedem Blocken 112 Schaden verursacht.\n\nDurch das Anbringen des Elementiumschildstachels wird der Gegenstand seelengebunden." }
entries[76442] = { ["name"] = "Pyriumwaffenkette", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nPyriumbarren\nPyriumwaffenkette\nWird beim Anlegen gebunden\n81\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Euren Trefferwert um 40 erhöht. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen der Waffenkette wird der Gegenstand seelengebunden." }
